"use client";

/* eslint-disable @next/next/no-img-element -- QR images are generated by our own API and printed as-is. */

import Link from "next/link";
import {
  BarChart3,
  BellRing,
  ChevronRight,
  Crown,
  Download,
  Grid2X2,
  IndianRupee,
  LayoutDashboard,
  Menu as MenuIcon,
  Printer,
  QrCode,
  Settings,
  ShoppingBag,
  Upload,
  Users,
  UtensilsCrossed
} from "lucide-react";
import type { LucideIcon } from "lucide-react";
import { useCallback, useEffect, useMemo, useState } from "react";
import { DashBrand } from "@/components/dash-brand";
import { categoryHindi, menuCategories, menuItems } from "@/data/menu";
import type { ServiceRequest, StoredOrder } from "@/lib/db";
import { SERVICE_LABELS } from "@/lib/time";

type AdminView = "overview" | "tables" | "menu" | "settings";

const navigation: { id: AdminView; label: string; icon: LucideIcon }[] = [
  { id: "overview", label: "Overview", icon: LayoutDashboard },
  { id: "tables", label: "Tables & QR", icon: Grid2X2 },
  { id: "menu", label: "Menu", icon: MenuIcon },
  { id: "settings", label: "Settings", icon: Settings }
];

const tables = Array.from({ length: 50 }, (_, index) => index + 1);
const pad = (value: number) => String(value).padStart(2, "0");

export function AdminDashboard() {
  const [view, setView] = useState<AdminView>("overview");
  const [orders, setOrders] = useState<StoredOrder[]>([]);
  const [requests, setRequests] = useState<ServiceRequest[]>([]);
  const [error, setError] = useState("");
  const [paymentQr, setPaymentQr] = useState<string | null>(null);

  const load = useCallback(async () => {
    try {
      const [ordersResponse, requestsResponse] = await Promise.all([
        fetch("/api/orders", { cache: "no-store" }),
        fetch("/api/service-requests", { cache: "no-store" })
      ]);
      if (!ordersResponse.ok || !requestsResponse.ok) throw new Error("Server not reachable");
      setOrders(((await ordersResponse.json()) as { orders: StoredOrder[] }).orders);
      setRequests(((await requestsResponse.json()) as { requests: ServiceRequest[] }).requests);
      setError("");
    } catch {
      setError("Live data load नहीं हुआ। Internet / server check करें।");
    }
  }, []);

  useEffect(() => {
    const initial = window.setTimeout(load, 0);
    const timer = window.setInterval(load, 5000);
    return () => {
      window.clearTimeout(initial);
      window.clearInterval(timer);
    };
  }, [load]);

  useEffect(
    () => () => {
      if (paymentQr) URL.revokeObjectURL(paymentQr);
    },
    [paymentQr]
  );

  const activeOrders = orders.filter((order) => !["SERVED", "CANCELLED"].includes(order.status));
  const tableStatus = useMemo(() => {
    const status = new Map<number, string>();
    activeOrders.forEach((order) => status.set(order.table_number, order.status));
    requests.forEach((request) => status.set(request.table_number, `Calling · ${SERVICE_LABELS[request.type] ?? request.type}`));
    return status;
  }, [activeOrders, requests]);
  const sales = orders.filter((order) => order.status !== "CANCELLED").reduce((sum, order) => sum + order.total, 0);
  const title = navigation.find((item) => item.id === view)?.label;

  return (
    <main className="dashboard-shell">
      <aside className="dash-sidebar">
        <DashBrand label="Owner console" />
        <nav>
          {navigation.map((item) => (
            <button type="button" key={item.id} className={view === item.id ? "is-active" : ""} onClick={() => setView(item.id)}>
              <item.icon size={20} />
              <span>{item.label}</span>
            </button>
          ))}
        </nav>
        <div className="dash-sidebar__bottom">
          <Link href="/kitchen">
            <UtensilsCrossed size={18} /> Kitchen display
          </Link>
          <Link href="/?table=1">
            <ChevronRight size={18} /> Customer view
          </Link>
        </div>
      </aside>

      <section className="dash-main">
        <header className="dash-topbar">
          <div>
            <p className="dash-kicker">The Royal Thadi · Ajmer</p>
            <h1>{title}</h1>
          </div>
          <span className={`live-pill ${error ? "live-pill--down" : ""}`}>
            <i /> {error ? "Offline" : "Live"}
          </span>
        </header>

        {error && <p className="dash-error">{error}</p>}

        {view === "overview" && (
          <>
            <div className="stat-grid">
              <article>
                <span>
                  <IndianRupee size={20} />
                </span>
                <small>Order value</small>
                <strong>₹{sales.toLocaleString("en-IN")}</strong>
                <p>
                  {orders.length} {orders.length === 1 ? "order" : "orders"} (latest 100)
                </p>
              </article>
              <article>
                <span>
                  <ShoppingBag size={20} />
                </span>
                <small>Active orders</small>
                <strong>{activeOrders.length}</strong>
                <p>In the kitchen queue</p>
              </article>
              <article>
                <span>
                  <Users size={20} />
                </span>
                <small>Busy tables</small>
                <strong>
                  {tableStatus.size}
                  <em>/50</em>
                </strong>
                <p>{50 - tableStatus.size} tables free</p>
              </article>
              <article className={requests.length ? "is-alert" : ""}>
                <span>
                  <BellRing size={20} />
                </span>
                <small>Service calls</small>
                <strong>{requests.length}</strong>
                <p>Waiter, water or bill</p>
              </article>
              <article>
                <span>
                  <BarChart3 size={20} />
                </span>
                <small>Average order</small>
                <strong>₹{orders.length ? Math.round(sales / orders.length) : 0}</strong>
                <p>Per order</p>
              </article>
            </div>

            <div className="dash-two-column">
              <section className="dash-panel">
                <div className="panel-title">
                  <div>
                    <p className="dash-kicker">Live floor</p>
                    <h2>Tables</h2>
                  </div>
                  <button type="button" className="dash-text-button" onClick={() => setView("tables")}>
                    QR codes <ChevronRight size={16} />
                  </button>
                </div>
                <div className="mini-table-grid">
                  {tables.map((table) => {
                    const status = tableStatus.get(table);
                    return (
                      <div key={table} className={`mini-table ${status ? (status.startsWith("Calling") ? "is-calling" : "is-busy") : ""}`} title={status ?? "Free"}>
                        <strong>{pad(table)}</strong>
                        <small>{status ? (status.startsWith("Calling") ? "Calling" : status.toLowerCase()) : "free"}</small>
                      </div>
                    );
                  })}
                </div>
              </section>

              <section className="dash-panel">
                <div className="panel-title">
                  <div>
                    <p className="dash-kicker">Latest</p>
                    <h2>Recent orders</h2>
                  </div>
                  <Link className="dash-text-button" href="/kitchen">
                    Kitchen <ChevronRight size={16} />
                  </Link>
                </div>
                {orders.length === 0 ? (
                  <div className="dash-empty">
                    <ShoppingBag size={28} />
                    <h3>No orders yet</h3>
                    <p>Table QR से आने वाले orders यहाँ दिखेंगे।</p>
                  </div>
                ) : (
                  <ul className="recent-orders">
                    {orders.slice(0, 8).map((order) => (
                      <li key={order.id}>
                        <b>#{String(order.id).padStart(3, "0")}</b>
                        <div>
                          <strong>Table {pad(order.table_number)}</strong>
                          <small>{order.items.reduce((sum, item) => sum + item.quantity, 0)} items</small>
                        </div>
                        <span className={`status-label status-${order.status.toLowerCase()}`}>{order.status}</span>
                        <em>₹{order.total}</em>
                      </li>
                    ))}
                  </ul>
                )}
              </section>
            </div>
          </>
        )}

        {view === "tables" && (
          <section className="dash-panel">
            <div className="panel-title">
              <div>
                <p className="dash-kicker">One QR per table</p>
                <h2>Tables 01–50</h2>
                <p className="panel-note">हर QR का order उसी table number के साथ kitchen में आएगा।</p>
              </div>
              <button type="button" className="dash-primary-button" onClick={() => window.print()}>
                <Printer size={18} /> Print all QR
              </button>
            </div>
            <div className="qr-grid">
              {tables.map((table) => (
                <article className="qr-card" key={table}>
                  <div className="qr-card__brand">
                    <Crown size={16} /> The Royal Thadi
                  </div>
                  <img src={`/api/qr?table=${table}`} alt={`QR code for table ${table}`} width={160} height={160} loading="lazy" />
                  <strong>Table {pad(table)}</strong>
                  <span className="qr-card__hint">Scan to order · स्कैन करें, ऑर्डर करें</span>
                  <a className="qr-card__download" href={`/api/qr?table=${table}`} download={`royal-thadi-table-${pad(table)}.png`}>
                    <Download size={16} /> Download
                  </a>
                </article>
              ))}
            </div>
          </section>
        )}

        {view === "menu" && (
          <section className="dash-panel">
            <div className="panel-title">
              <div>
                <p className="dash-kicker">Live on customer menu</p>
                <h2>
                  Menu · {menuItems.length} items · {menuCategories.length} categories
                </h2>
                <p className="panel-note">Price बदलना हो तो बताइए; online editing अगले step में जुड़ेगा।</p>
              </div>
            </div>
            <div className="menu-admin">
              {menuCategories.map((category) => (
                <section key={category}>
                  <h3>
                    {category} <span lang="hi">{categoryHindi[category]}</span>
                  </h3>
                  <ul>
                    {menuItems
                      .filter((item) => item.category === category)
                      .map((item) => (
                        <li key={item.id}>
                          <span>{item.name}</span>
                          <b>₹{item.price}</b>
                        </li>
                      ))}
                  </ul>
                </section>
              ))}
            </div>
          </section>
        )}

        {view === "settings" && (
          <div className="settings-grid">
            <section className="dash-panel setting-card">
              <span className="setting-icon">
                <QrCode size={24} />
              </span>
              <p className="dash-kicker">Payments</p>
              <h2>Payment QR</h2>
              <p className="panel-note">अभी यह सिर्फ preview है। Online database जुड़ने के बाद यह customers को bill के साथ दिखेगा।</p>
              <label className="upload-box">
                {paymentQr ? (
                  <img src={paymentQr} alt="Payment QR preview" width={200} height={200} />
                ) : (
                  <>
                    <Upload size={26} />
                    <strong>Upload payment QR</strong>
                    <span>PNG or JPG</span>
                  </>
                )}
                <input
                  type="file"
                  accept="image/png,image/jpeg"
                  onChange={(event) => {
                    const file = event.target.files?.[0];
                    if (file) setPaymentQr(URL.createObjectURL(file));
                  }}
                />
              </label>
            </section>
            <section className="dash-panel setting-card">
              <span className="setting-icon">
                <Crown size={24} />
              </span>
              <p className="dash-kicker">Restaurant</p>
              <h2>The Royal Thadi</h2>
              <dl className="setting-fields">
                <div>
                  <dt>Phone</dt>
                  <dd>+91 99829 09045</dd>
                </div>
                <div>
                  <dt>Tables</dt>
                  <dd>50</dd>
                </div>
                <div>
                  <dt>Location</dt>
                  <dd>FJQ4+35W, Nausar Ghati, Ajmer 305004</dd>
                </div>
              </dl>
            </section>
          </div>
        )}
      </section>
    </main>
  );
}
